import 'package:flutter/foundation.dart';

/// Non-verbal Milo sounds (spec 2D): 14 short synthesized cues generated by
/// `tools/make_sounds.py` into `assets/sounds/`. Playback goes through a
/// [SoundBackend] so the choice of audio package stays a one-line swap.
///
/// Playback-package decision (28 Oct 2026, PROVISIONAL): `audioplayers` is
/// the intended backend (simple asset playback, widely used). Not added yet:
/// this environment has no network to resolve a version, and an untested
/// native dependency could break CI. Until the human adds it, sounds queue
/// silently and every cue keeps its haptic/visual equivalent.

/// The 14 cues and their lengths in ms (all < 600). Single source shared by
/// the generator script (duplicated there; the test asserts the names match).
const kSoundNames = ['wake', 'tap_giggle', 'think_hmm', 'success', 'soft_error', 'mic_on', 'mic_off',
  'hum', 'yawn', 'sprout_boing', 'page', 'whoosh', 'sparkle', 'aww'];

abstract class SoundBackend {
  Future<void> play(String asset, double volume);
}

class NoopSoundBackend implements SoundBackend {
  @override
  Future<void> play(String asset, double volume) async {}
}

class MiloSounds {
  SoundBackend backend;
  bool enabled = true;
  double volume = .8;
  MiloSounds({SoundBackend? backend}) : backend = backend ?? NoopSoundBackend();

  @visibleForTesting
  final playedForTest = <String>[];

  /// Plays [name] when every gate passes: sounds on, not quiet, a real
  /// presence (never over AAC speech, never in Chip/Hidden). Volume scales
  /// per cue loudness. Silent no-op otherwise — never an error.
  Future<void> play(String name, {required bool quiet, required bool aac, required String presence, double loud = 1}) async {
    if (!kSoundNames.contains(name)) return;
    playedForTest.add(name);
    if (!enabled || quiet || aac || presence == 'chip' || presence == 'hidden' || volume <= 0) return;
    try { await backend.play('assets/sounds/$name.wav', (volume * loud).clamp(0.0, 1.0).toDouble()); } catch (_) {}
  }
}
